using static StrataLint.Scribe.FormulaDsl;
using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Arith.FibonacciAtomic.Observer.Constructor;

internal sealed class NativeMixedImageConstructionDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/Arith/FibonacciAtomic/Observer/Constructor/NativeMixedImageConstruction.";

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Expression naming and unrestricted mixed native soundness",
        H("Original expressions and their named equations"), Blocks(
            Paragraph(Text("Source is the algebra of finite ordered Boolean trees. Pairing is its actual constructor, and rho is the interpreted native substitution. MixedExpr uses fixed ground trees, fixed natural powers of original variables, and pairing. A positive presentation is a finite list of pairs of these expressions. The list may be empty or contain repetitions. X retains every original variable, including unused variables; X may be Fin d, also when d is zero. No tree size or depth bound is imposed.")),
            Def("Name", "Disjoint input and auxiliary namespaces", "Name X is X plus MixedExpr X. Inputs are injected on the left and expression names on the right. Every repeated use of an expression has the same auxiliary name. This namespace itself is not finite: the finite lowering emits only the definitions needed by the supplied finite expressions. Reindexing its finite support by a finite presentation remains a separate construction."),
            Def("root", "Name an original expression", "root injects an expression into the auxiliary namespace without changing its variables or ground parameters."),
            Def("groundDefinitions", "Expand ground parameters into finite native syntax", "A Boolean leaf has its primitive rank zero or one. A pair recursively includes both ground definitions and the pairing equation for their roots. This operation terminates by recursion on the supplied finite ground tree."),
            Def("definitions", "Lower every expression constructor", "A residual occurrence rho to power a of x becomes a shift from the original input name x to its expression root. A pair includes the definitions of its two children and an ordinary native pairing equation between their roots. Repeated definitions are retained."),
            Def("flatten", "Retain all positive equalities", "For each original pair of expressions, flatten concatenates both lists of definitions and an equality between the two expression roots. This is a concrete terminating function on the original syntax. It does not assume that the original positive equations already hold."),
            Def("extend", "Evaluate every named subexpression at the same source assignment", "extend keeps the input assignment on the left and evaluates the named expression on the right. No new choice of original source is made."),
            Thm("flatten_exact", "Exact lowering at the original assignment", "All original positive expression equalities hold at v if and only if every emitted named equation holds at extend v. For the forward direction, ground recursion verifies both primitive leaves and actual native pairs; expression recursion verifies each fixed power and each ordered pair. The reverse direction reads the emitted root equality for every supplied comparison. Unused input values remain those of v."),
            Thm("expression_branch_exact", "Finite canonical branches from original expression syntax", "The original expression equalities hold exactly when one member of branches(flatten E) holds on the actual canonical encodings of extend v. The concrete lowering theorem supplies the native named equations. The existing exact constructor-case theorem then chooses ordinary or collapse cases from those same actual values. This finite branch list does not enumerate scalar ranks or native sources, and still retains code equations rather than unrestricted image charts."),
            Thm("flatten_expansion_sound", "Expand arbitrary ambient branch solutions", "For any selected branch of flatten E, let u assign arbitrary finite ambient codes to names and satisfy that branch's code equations. Then expanding u on the original input names satisfies every original expression equality. Induction through the definitions identifies each expanded auxiliary value with evaluation of its original expression. Existing branch soundness supplies interpreted shifts, ordinary pairs, and the primitive collapse recurrence. Normality and injectivity of expansion are not premises. In particular an ordinary pair of consecutive primitive ranks may collapse after filling without invalidating its native pairing equation."),
            Paragraph(Text("Finite scalar guards and native templates.")), 
            Def("Scalar", "Affine natural rank atoms", "A scalar is a fixed natural constant, or n(i)+a for a natural parameter n(i) and a fixed natural offset a. Thus its integer interpretation is affine, with coefficient zero or one."),
            Def("Scalar.value", "Read a scalar parameter", "Scalar.value evaluates the constant or the parameter with its fixed offset in the natural numbers."),
            Def("Pattern", "Finite mixed ambient syntax", "A pattern is an explicit scalar leaf, a residual native block of sort i with a fixed natural offset a, or a pair of patterns. Different residual sorts receive independently supplied native values. Equal values across different sorts are permitted."),
            Def("Decoration", "Decorate exactly the actual shape leaves", "Decoration k m s is defined recursively on the supplied free-shape term s. An explicit primitive leaf carries a Scalar k. A residual leaf carries an element of Fin m and a fixed natural offset. A pair carries the decorations of its two children. Empty scalar or native dimensions therefore require no nonexistent selector when the corresponding leaves are absent."),
            Def("assemble", "Construct every named mixed pattern", "assemble traverses the actual free-shape term with its dependent decoration: explicit leaves become scalar patterns, residual occurrences become shifted native blocks, and binary nodes become pairs. A named family s and decorations d thus give the concrete pattern of every original and auxiliary name. Shared names reuse the same supplied term and decoration."),
            Def("Pattern.code", "Assemble ambient codes before expansion", "Scalar leaves become primitive codes; a residual block becomes shiftCode a (encode (z i)); pairs become raw ambient pairs. Pair assembly uses no smart normalization and adds no normality test."),
            Def("Pattern.template", "Return the established native mixed syntax", "A constant scalar becomes a fixed ground tree; a parameter scalar becomes the ranked residual rho to power a of T(n i); a block becomes rho to power a of z i; pairs remain actual native pairs. These are RankedExpr templates, using the existing rankedEval interpretation. Structural recursion proves that expanding Pattern.code is exactly rankedEval of this template."),
            Def("Guard", "A finite conjunction of affine integer equalities", "Guard is a list of pairs of scalar atoms. It has no native parameter fields."),
            Def("Guard.Holds", "The arithmetic domain", "Each scalar pair is required to have equal integer values. Its arguments range over all natural scalar tuples. No positivity, shape, disequality, source bound, or normality predicate on residual native values occurs in this guard."),
            Def("compare", "Extract scalar equalities from matching decorated syntax", "Two scalar leaves emit their affine equality. Two blocks succeed exactly when their residual sort and fixed offset agree syntactically, emitting no arithmetic condition. Two pairs recursively compare corresponding children and concatenate their guards. All other constructor combinations fail. Success is a sufficient symbolic comparison; no completeness of this procedure over arbitrary native equalities is asserted. In particular accidental equal native parameters are allowed, while the procedure need not recognize every equality caused by them."),
            Def("Scalar.shift", "Translate explicit ranks", "A fixed natural shift adds its offset to constants and parameter offsets."),
            Def("Pattern.shift", "Translate every ambient leaf", "Translation recursively shifts explicit scalar leaves and adds the supplied shift to every residual block offset. Pair structure is preserved. Its assembled code equals shiftCode of the unshifted assembled code."),
            Def("branchComparisons", "Extract every selected branch comparison", "Primitive equations compare the assigned output pattern with their fixed scalar. Shift equations compare the output with syntactic translation of the input; ordinary equations compare it with a raw pair; equalities compare their two named patterns. A collapse uses a supplied scalar atom c(b) and emits all three equations: left rank value(c(b))+1, right rank value(c(b)), and output rank value(c(b))+2. The same scalar is shared in those three comparisons."),
            Def("collect", "Combine a finite comparison family", "collect recursively runs compare on every pattern pair and concatenates the resulting scalar guards. Failure discards the attempted decorated syntax. Success proves all ambient comparisons for every native filling satisfying the combined scalar guard."),
            Thm("guarded_mixed_sound", "Unrestricted native soundness of extracted guards", "Take any actual finite branch B of the lowered original expressions, any named free-shape family s, a dependent decoration d of every actual shape leaf, and an assignment c of scalar atoms to collapse equations. If collect succeeds on every comparison extracted from B, then for every natural tuple n satisfying its returned affine guard and every arbitrary native tuple z, the original expressions are equal at the outputs rankedEval n z (assemble(s(inl x),d(inl x))). Scalar comparisons give equal primitive ranks. Matching residual blocks have identical shifts of the same encoded native parameter. Matching pairs reconstruct equal ambient codes. The three collapse comparisons provide their explicit natural rank. Existing arbitrary-code branch expansion then proves the original native equations. The hypotheses are finite syntactic comparison success and the extracted scalar equations, rather than a hypothesis asserting the desired original native equalities."),
            Paragraph(Text("These results establish concrete lowering and the arbitrary-filling soundness chain. They do not extract all decorations and their finite scalar indexing from an arbitrary successful shape unifier, prove that every consistent branch admits successful comparison extraction, synthesize the finite list of image charts, or prove same-source completeness of that list. Those steps require occurrence decoration and the signed-cycle, minimum-base and effective-potential supplier. The public universal finite image-cover theorem therefore requires these additional constructions. No existence of potentials or of an exact cover is assumed here."))
        )));

    private static DocumentBlock Def(string name, string title, string text) =>
        Entry(name, title, text, DescribeRole.Definition);
    private static DocumentBlock Thm(string name, string title, string text) =>
        Entry(name, title, text, DescribeRole.Theorem);
    private static DocumentBlock Entry(string name, string title, string text, DescribeRole role) =>
        Describe.Lean(DescribeId.Create("mixed-native-" + name.Replace('.', '-').ToLowerInvariant()),
            DeclarationHandle.Create(Prefix + name), H(title), StatementSource.WithoutFormula(),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text(text))), role);
}
